return {
  [ [[v5748eaic9ne8]] ] = { t = [[血统奥秘的适用范围]], q = [[血统奥秘赋予的加值，是作用于术士施展的所有法术，还是只作用于术士法术列表上的法术？]], a = [[血统奥秘的效果作用于该血统的角色所施展的所有法术，而不仅限于使用术士法术位施展的法术。

通用规则：如果一项职业能力会修正你的施法，它就作用于你所有职业的法术，而不只是授予该能力的那个职业的法术。（例外：该职业能力特别说明它只作用于该职业的法术。）]], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ne8]], cat = [[FAQ]], ai = false, pages = { [[术士]] } },
  [ [[v5748eaic9rae]] ] = { t = [[施法进阶职业与血统法术]], q = [[如果我在一项会提升施法能力的进阶职业中获得等级，能因此获得我血统的更高环血统法术吗？]], a = [=[不能。同样，它也不会给你额外的血统专长。

如果你是先知，它不会给你额外的秘示域法术。（不过它会给你更高环的治疗或造成伤害法术，因为这些属于先知的法术职业特性。）

如果你是女巫，它不会给你额外的庇护主法术。

如果你是法师，它不会让你获得更高环的学派之力。

以此类推。

提升施法能力的进阶职业只会提升施法者等级、每日法术数，以及（对自发施法者而言）已知法术数——也就是你原职业的法术职业特性描述中的那些施法特性。

（注意：[[龙脉术士]]职业拥有【龙之血脉】能力，其中明确写明你能获得血统力量和血统法术；这是该职业自身的特殊能力，并不是用进阶职业提升施法能力时的通常情形。）]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rae]], cat = [[FAQ]], ai = false, pages = { [[术士]], [[进阶职业]] } },
  [ [[v5748eaic9qpr]] ] = { t = [[双持追击武器]], q = [=[如果我双持两把[[追击]]武器，每轮能多得两次攻击吗？]=], a = [[不能。追击的收益与类似效果不叠加，而“第二把追击武器”就是类似效果。]], book = [[核心规则书]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qpr]], cat = [[FAQ]], ai = true, pages = { [[追击]] } },
  [ [[v5748eaic9qny]] ] = { t = [[法术熟稔与新职业]], q = [=[[[炼金术师]]、[[魔战士]]或[[女巫]]能选择这个专长吗？]=], a = [[按字面规定，不能，因为该专长的先决条件是“1级法师”。

不过，这个专长是在炼金术师、魔战士和女巫这些职业出现之前写成的，所以允许这些职业选择该专长、并把它的效果用于炼金术师的公式本、魔战士的法术书或女巫的魔宠，作为一条房规是完全合理的。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qny]], cat = [[FAQ]], ai = false, pages = { [[法术熟稔]] } },
  [ [[v5748eaic9o6x]] ] = { t = [[类法术能力的有效法术环级]], q = [[牧师领域、术士血统、法师学派和部分其他职业特性会给予不基于具体法术的类法术能力。这些能力的有效法术环级是多少？]], a = [=[这些类法术能力的有效法术环级，等于该职业的角色在获得该能力的等级时通常能施展的最高环级法术。

例如，1级的元素血统[[术士]]拥有类法术能力元素射线。因为1级术士可用的最高环级法术是1环，所以该类法术能力视为1环法术。9级的元素血统术士拥有类法术能力[[元素爆发]]。因为9级术士可用的最高环级法术是4环，所以该类法术能力视为4环法术。]=], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o6x]], cat = [[FAQ]], ai = false, pages = { [[类法术能力]] } },
  [ [[v5748eaic9ofm]] ] = { t = [[类法术能力与法术列表]], q = [[拥有类法术能力的生物，在激活法术完成型或法术触发型物品时，是否算作那个法术在它的法术列表上？]], a = [[不算。类法术能力不是法术，拥有类法术能力也不属于某个职业法术列表的一部分，因此它不会赋予该生物激活法术完成型或法术触发型物品的能力。]], book = [[核心规则书]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ofm]], cat = [[FAQ]], ai = true, pages = { [[类法术能力]] } },
  [ [[v5748eaic9qt6]] ] = { t = [[类法术能力是奥术还是神术]], q = [[我怎么判断一个类法术能力是奥术的还是神术的？]], a = [[通用怪物规则中关于类法术能力的条文写道：“某些类法术能力所复制的法术，在由不同职业的角色施放时效果不同。怪物的类法术能力默认对应于术士/法师版本。如果这个法术不属于术士/法师法术，那么按此顺序默认：牧师、德鲁伊、吟游诗人、圣武士、游侠。”

对于由生物的种族或类型获得的类法术能力（包括PC种族），应适用同样的规则：该生物的类法术能力默认为术士/法师版本。如果该法术不属于术士/法师法术，则按此顺序默认：牧师、德鲁伊、吟游诗人、圣武士、游侠。

对于由职业获得的类法术能力，用该职业的法术类型（奥术或神术）来判定这个类法术能力是奥术的还是神术的。如果该职业不施展法术，则按上述种族或类型类法术能力的规则处理。]], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qt6]], cat = [[FAQ]], ai = true, pages = { [[类法术能力]] } },
  [ [[v5748eaic9qow]] ] = { t = [[类法术能力与先决条件]], q = [[对于先决条件或要求，拥有类法术能力的生物是否算作能够施展那个法术？]], a = [=[只有当先决条件明确点出某个法术的名称时才算。例如，[[次元灵巧]]专长（《极限战斗》）的先决条件是“能使用【遁术】职业特性，或可施展[[任意门]]”；[[犬魔]]拥有类法术能力任意门，因此满足该专长“可施展任意门”的先决条件。但犬魔的任意门并不满足诸如“能施展4环法术”或“能施展奥术法术”之类的要求。]=], book = [[核心规则书]], date = [[2015/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qow]], cat = [[FAQ]], ai = true, pages = { [[类法术能力]] } },
  [ [[v5748eaic9ucw]] ] = { t = [[“如同某法术”的能力的DC]], q = [[对于写着“如同某个法术一样生效”的能力，我该如何计算它的DC？]], a = [[有些如同法术生效的能力会直接告诉你它的DC，例如吟游诗人的【迷魂】表演。如果一项能力没有说明它的DC，其DC为 10 + 法术环级 + 授予该能力的职业的关键施法属性修正（若无此职业则用魅力修正）。

如果该法术在不同职业的法术列表中环级不同：若授予该能力的职业的法术列表上有这个法术，就用该职业的法术环级；否则用最合适的法术环级（通常奥术能力取术士/法师的环级，神术能力取牧师的环级，通灵能力取通灵者的环级）。]], book = [[核心规则书]], date = [[2016/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ucw]], cat = [[FAQ]], ai = true, pages = { [[类法术能力]] } },
  [ [[v5748eaic9tza]] ] = { t = [[法术辨识辨识的是什么]], q = [=[我用[[法术辨识]]来辨识法术时，到底辨识的是什么？是成分吗？可比如类法术能力就没有成分。如果只能辨识成分，是不是就意味着我不能对使用类法术能力（或不带言语、姿势、材料成分的法术）的人发动借机攻击，也不能准备动作射箭去打断类法术能力？如果辨识的是别的什么，我又怎么知道那是什么？]=], a = [[尽管《核心规则书》没有直接写明，但游戏系统的许多部分都是以“所有法术都有各自的显现”为前提运作的，无论法术是否像火球术那样同时产生明显的视觉效果。你可以从Pathfinder各产品的各种插图中看到一些例子，借以启发你如何描述法术的显现，但最终的具体细节由你们的团体决定，甚至可以取决于单个施法者的个人风格。无论如何，这些显现显然是某种魔法，即便对外行人也是如此；这就避免了使用类法术能力、通灵魔法之类的施法者在非战斗场合对非施法者为所欲为。确实存在一些特殊能力（《极限诡道》中很可能还会出现更多），专门帮助施法者用诡计引开人们对这些显现的注意、使其不被察觉，但它们总会给旁观者某种识破这一骗局的机会。]], book = [[核心规则书]], date = [[2015/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9tza]], cat = [[FAQ]], ai = true, pages = { [[法术辨识]] } },
  [ [[v5748eaic9o64]] ] = { t = [[跳跃攻击与同伴的方格]], q = [=[我能用[[跳跃攻击]]从同伴所在的方格发动攻击吗？]=], a = [=[让我们用一张5尺宽走廊的示意图来帮助理解这个问题。句点代表空方格，A是正在行动的角色，数字是A的同伴，X是怪物。

<code>. . . . . A 1 2 3 X</code>

以这张图为模型，问题就是：“我能用跳跃攻击从A移动到3，在3的方格里攻击怪物，然后移回A并结束我的回合吗？”

回答是“可以”。理解的关键在于通用规则：“你不能在被占据的方格里结束移动。”跳跃攻击是一个[[整轮动作]]；它不是“一个移动动作，接着一次攻击，再接着另一个移动动作”，而是一次连续的移动，攻击发生在中间。因此，用跳跃攻击时，直到你结束本回合的移动，你的移动才算结束。

换个角度看，如果角色只是想从A移动到3、再移回A，这是合法的移动，因为他并不是在3结束移动，而是在回到A时结束移动。用了跳跃攻击，角色同样不是在3结束移动；这个专长只是赋予他在从A到3再到A的连续移动过程中进行一次攻击的能力（不管这次攻击发生时他是否身处被占据的方格）。

（即便速度只有15尺，一个角色先移动15尺从A到3、再移动15尺从3回到A，也不是在3结束移动……先用一个移动动作移动15尺、再用一个标准动作移动15尺，并不意味着他真的在移动中途停了下来去切换动作。）]=], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o64]], cat = [[FAQ]], ai = false, pages = { [[跳跃攻击]] } },
  [ [[v5748eaic9nad]] ] = { t = [[首个生命骰与天赋职业奖励]], q = [[哪些生物在第1级（第1个生命骰）取最大生命值？哪些生物能获得天赋职业对生命值或技能点的奖励？]], a = [=[第1个生命骰来自PC用职业的生物，该生命骰取最大生命值。目前的PC用职业有：炼金术师、奥能师、野蛮人、吟游诗人、血脉狂怒者、拳师、骑士、牧师、德鲁伊、战士、枪手、猎人、调查员、审判者、魔战士、武僧、先知、圣武士、游侠、盗贼、萨满、歌者、杀手、术士、召唤师、游荡剑客、战斗祭司、女巫和法师（包括这些职业的变体职业、子职业和其他变体）。

第1个生命骰来自NPC职业（[[导师]]、[[望族]]、[[平民]]、[[专家]]、[[武者]]）或种族生命骰（如大多数怪物）的生物，该生命骰不取最大生命值。

所有拥有职业等级的生物（包括拥有NPC职业等级的生物，或拥有职业等级的怪物）都可以选择一个天赋职业，并获得正常的天赋职业收益。生物绝不会因种族生命骰而获得天赋职业收益。

例如，1级人类武者可以选择“武者”作为他的天赋职业，并在每次提升该职业等级时选择额外1点生命值或1点技能点。一只通常拥有3个种族生命骰、没有职业等级的熊地精没有天赋职业，也没有天赋职业收益；但如果这只熊地精获得了1级盗贼，他就可以选择“盗贼”作为天赋职业，并在每次提升该职业等级时选择额外1点生命值或1点技能点。]=], book = [[核心规则书]], date = [[2010/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nad]], cat = [[FAQ]], ai = false, pages = { [[创造怪物]] } },
  [ [[v5748eaic9pyv]] ] = { t = [[全力攻击中的击破]], q = [[我能在一次全力攻击中进行多次击破尝试吗？击破的文字说我可以在攻击动作中取代一次近战攻击来击破，而这严格来说并不是全力攻击动作。]], a = [[可以。这段文字有点不清楚。与其写成“作为攻击动作的一部分，取代一次近战攻击”，文本应当写成“取代一次近战攻击”，这样你就可以在一轮内进行多次击破尝试，甚至可以用一次击破尝试来取代一次借机攻击。]], book = [[核心规则书]], date = [[2012/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9pyv]], cat = [[FAQ]], ai = false, pages = { [[击破]] } },
  [ [[v5748eaic9r43]] ] = { t = [[同一来源的临时生命值]], q = [[同一来源的临时生命值会叠加吗？]], a = [=[不会。通常，来自同一来源的效果不叠加（《核心规则书》第208页，合并魔法效果）。虽然临时生命值不是“加值”，但这条原则依然适用。

这样就避免了一个会能量吸取（每次使用获得5点临时生命值）的生物，在PC赶来与它战斗之前，榨干整个100人的村庄、给自己攒出500点临时生命值。

来自不同来源的临时生命值（例如[[援助术]]、一次能量吸取和[[吸血鬼之触]]法术）仍然可以彼此叠加。]=], book = [[核心规则书]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9r43]], cat = [[FAQ]], ai = false, pages = { [[伤害和死亡]] } },
  [ [[v5748eaic9vs4]] ] = { t = [[临时生命值与真言术：死]], q = [=[在判定我的当前生命值总数以决定[[真言术：死]]这类效果时，要把临时生命值算进去吗？]=], a = [[要。把你的临时生命值与剩余的正常生命值相加，作为你的生命值总数，用于那些依据当前生命值总数而产生不同效果的效果。]], book = [[核心规则书]], date = [[2017/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vs4]], cat = [[FAQ]], ai = true, pages = { [[伤害和死亡]], [[真言术：死]] } },
  [ [[v5748eaic9rrc]] ] = { t = [[准备溅射武器的整轮动作]], q = [[“准备溅射武器”这个整轮动作（第183页）适用于所有溅射武器的使用吗？]], a = [=[不。投掷溅射武器是一次攻击，而大多数溅射武器在使用前不需要任何准备，因为它们在命中时就会爆炸或生效（你只需要把它从存放处取出，再投出去，并为此花费相应的动作）。

表格里的“准备溅射武器”一项，只是指把一瓶灯油准备成溅射武器。灯油的装备说明写道：

灯油：一品脱灯油可以在提灯或油灯里燃烧6小时。你也可以把一瓶灯油当作溅射武器使用。规则同[[炽火胶]]（见表6-9特殊物质与物品），只是给瓶子装上引信需要一个整轮动作。投出之后，瓶子有50%的几率成功点燃。

因此，表里列出的这个整轮动作，指的是给一瓶灯油装上引信并点燃，好让你把它当作溅射武器使用。（“准备”这瓶油并不包括把它投出去，投出去是另一个攻击动作。）]=], book = [[核心规则书]], date = [[2014/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rrc]], cat = [[FAQ]], ai = false, pages = { [[特殊攻击]], [[灯油]] } },
  [ [[v5748eaic9n8a]] ] = { t = [[对起身的俯卧目标摔绊]], q = [[当一个俯卧的角色起身并引发借机攻击时，我能用这次借机攻击再次摔绊他吗？]], a = [[不能。借机攻击会在触发它的动作结算之前发生。此时目标仍处于俯卧状态（你进行这次攻击时照常获得相应的加值）。由于摔绊战技并不会阻止目标的动作，目标随后仍会站起。]], book = [[核心规则书]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9n8a]], cat = [[FAQ]], ai = false, pages = { [[摔绊]] } },
  [ [[v5748eaic9qg0]] ] = { t = [[真知术与魅影杀手]], q = [=[真知术能保护你不受[[魅影杀手]]的影响吗？]=], a = [[能。真知术让你“如实看见一切事物”。魅影杀手是幻术（魅影幻觉）法术，它直接在目标的心灵中创造一个影像；有真知术的目标会（在心灵上）看见这个影像，同时（在身体上）看见那里其实什么也没有，因此会立刻意识到这个心灵影像其实并不真实。因为魅影杀手写明目标“可进行一次意志豁免以识破这个影像并非真实”，有真知术的生物会自动通过这次豁免（不用投骰），因此永远不必面对魅影杀手中强韧豁免的部分。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qg0]], cat = [[FAQ]], ai = true, pages = { [[真知术]], [[魅影杀手]] } },
}